            total += i;
        }
        return total;
    }

    // Demonstrates while loop countdown
    function countdown(uint256 count) public pure returns (uint256) {
        uint256 remaining = count;
        while (remaining > 0) {
            remaining--;
        }
        return remaining;
    }
}

